import {COMBAT_ASSUMPTION_KEYS,simulationParams,IDS,PASS,models,coverage,chance,specializationRole,ROLE_LABELS} from './simulator.js?v=automatic-key-nodes-2';
const fields=[
 ['rangeDamage','Урон дальнего боя, %'],['magicDamage','Урон магии, %'],
 ['selfDurationExtension','Час преодоления: Длительность ▲, с (гипотеза)'],
 ['resistance','Сопротивление умениям цели'],['selfSkillBoost','Час преодоления: повышение урона умений'],['targetResistanceDrop','Час отмщения: снижение сопротивления'],['lightMaxBonus','Свет доблести: максимальный урон'],['lightOpeningMultiplier','Свет доблести: начальный множитель (гипотеза)'],['lightOpeningSeconds','Свет доблести: окно усиления, с'],
 ['crossMin','Арбалет: мин. урон'],['crossMax','Арбалет: макс. урон'],['offMin','Парный арбалет: мин. урон'],['offMax','Парный арбалет: макс. урон'],['wandMin','Жезл: мин. урон'],['wandMax','Жезл: макс. урон'],
 ['critR','Крит. удар: дальний бой'],['critM','Крит. удар: магия'],['heavyR','Мощная атака: дальний бой'],['heavyM','Мощная атака: магия'],
 ['critDamage','Критический урон, %'],['boost','Повышение урона умений'],['bonus','Дополнительный урон'],['offhand','Атака парным оружием, %'],
 ['cooldown','Скорость восстановления, %'],['speed','Скорость атаки, %'],['interval','Интервал автоатаки, с'],['buffDuration','Длительность баффов, %'],
 ['mana','Максимум маны'],['regen','Восстановление маны'],['regenPeriod','Период восстановления, с'],['efficiency','Эффективность расхода маны, %'],['hp','Максимум здоровья'],['healing','Эффективность исцеления, %'],
 ['species','Повышение урона по типу цели'],['pve','Общий множитель PvE'],['defense','Защита манекена'],['defenseK','Константа защиты'],['ratingK','Константа рейтингов'],['animationFloor','Минимум на действие, с'],['latency','Задержка между действиями, с']];
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:1});
const names={'auto':'Автоатака арбалета','gale':'Взрыв «Шквал»','mark-hit':'Метка: попадания','mark-explosion':'Взрыв метки','nature-hit':'Гнев природы: снаряды','nature-lightning':'Гнев природы: молния','curse-explosion':'Взрыв оставшегося урона проклятий'};
export function setupSimulation(getState,catalog,apply,profile){
 const controlIds=['sim-mode','sim-budget','sim-night','sim-auto','sim-dotcrit','sim-formula'];
 let assumptions={},worker=null,result=null,runInput=null,dirty=false,lastState=JSON.stringify(getState());
 const root=$('simulation');
 root.innerHTML=`<div class="section-head"><div><p class="eyebrow">ОДНА ЦЕЛЬ · 300 СЕКУНД</p><h2>Симуляция и поиск ротации</h2></div><span class="counter">Экспериментальная модель</span></div>
 <p class="weapon-in-hand"><b>Оружие в руках: арбалет</b><span>Автоатаки — арбалетом. Умения жезла рассчитываются по диапазону жезла. Основное оружие в этой модели фиксировано.</span></p><p class="notice">Умения: эпический уровень 5. Исключение — Гнев природы: пока данные RU уровня 4, коэффициенты уровня 5 не подтверждены.</p><p class="hint">Неподвижный манекен без ответных атак. Результат — средний DPS модели, а не подтверждённый DPS в RU.</p>
 <div class="sim-controls"><label>Что подбирать<select id="sim-mode"><option value="selected">Приоритеты моей панели (состав фиксирован)</option><option value="all">Активные + специализации: до 100 очков + ротация</option></select></label><label>Глубина поиска<select id="sim-budget"><option value="180">180 вариантов</option><option value="600">600 вариантов</option></select></label></div>
 <p class="hint">Моя панель: перестановка приоритетов без замены умений. Полный подбор: до 12 поддерживаемых активных умений, специализации в пределах 100 очков и приоритеты. Пассивные и защитное умение остаются твоими. В режиме «Моя панель» специализации фиксированы.</p><p id="sim-source-note" class="micro"></p>
 <details><summary>Характеристики персонажа для расчёта</summary><p class="micro">Рассчитываются из выбранной сборки и обновляются при её изменении.</p><div id="sim-character-fields" class="sim-fields"></div></details>
 <details id="sim-params"><summary>Условия боя и допущения модели</summary><label>Формула усиления и сопротивления<select id="sim-formula"><option value="rutl">RUTL / WTFOMG PvE — отдельные множители</option><option value="difference">Rabubu29 — разность рейтингов (сравнение)</option></select></label><p class="micro">Источники расходятся. Основной вариант — RUTL. Альтернативный считает разность рейтингов и допускает снижение сопротивления ниже нуля; для RU это требует замера. Переключение меняет модель, а не характеристики.</p><div id="sim-fields" class="sim-fields"></div><div class="sim-toggles"><label><input id="sim-night" type="checkbox"> Ночь («Дар небытия»)</label><label><input id="sim-auto" type="checkbox" checked> Автоатака в паузах</label><label><input id="sim-dotcrit" type="checkbox"> Криты DoT: бонус крит. урона без максимума оружия (Rabubu29; проверить RU)</label></div></details>
 <details><summary>Время применения и PvE-множители умений</summary><p class="micro">Время взято из каталога; соответствие реальной блокировке действий нужно замерить в RU. Множители по умолчанию 1, кроме явного ×1,3 у «Луча погибели». Неизвестные скрытые бонусы не подставлены.</p><div class="sim-table-wrap"><table><thead><tr><th>Умение</th><th>Базовый откат ур. 5, с</th><th>Время, с</th><th>Множитель PvE</th></tr></thead><tbody id="sim-models"></tbody></table></div></details>
 <details><summary>Что учитывает модель</summary><div class="model-notes"><p>Рассчитываются попадания, откаты, мана, проклятия, взрыв оставшихся тиков, метка и её накопление, дополнительные снаряды, парные атаки, «Шквал», сброс Скоростной стрельбы и часть пассивных эффектов. Полный поиск меняет состав активных умений, их специализации в пределах 100 очков и приоритеты; пассивные и защитное умение фиксированы. Неподдерживаемые эффекты перечислены ниже.</p><p>Шаг боя 0,05 с. Используются математические ожидания критов, мощных и парных атак; это не случайные прогоны. Для критов берётся максимальный урон, для обычных ударов — средний. Вероятность рейтинга r: r/(r+K). В основной модели усиление даёт множитель 1 + SDB/(SDB+K), сопротивление — 1 − SDR/(SDR+700). Альтернатива Rabubu29: 1 + Δ/(|Δ|+K), где Δ = SDB − SDR. Защита — на 1/(1+DEF/Kзащ). Дополнительный урон прибавляется после множителей. Для периодического урона он не применяется. Взрыв проклятий использует оставшийся урон один раз: повторно крит, мощный удар и множители к нему не применяются; трактовка двух ударов требует проверки в игре.</p><p>Манекен: попадания и наложение ослаблений гарантированы, устойчивость, блок и сопротивления нулевые. Автоатаки идут только в паузах. Час отмщения снижает сопротивление умениям цели; Час преодоления повышает урон умений персонажа. Бафф на себя не считается проклятием и не запускает эффекты ослабления. Свет доблести повышает максимальный урон на 50. Начальное усиление — редактируемая гипотеза, по умолчанию отключена. Для парного арбалета используется отдельный диапазон; если он не указан, временно используется диапазон основной руки. Постоянный бонус «Амбидекстра» уже учтён в диапазоне парного оружия сборки. Дробные стаки вероятностных эффектов и сокращение откатов — приближение. Мана восстанавливается равномерно, по умолчанию указанное количество за 10 с. «Баланс энергий» расходует здоровье; «Кровавый пакт» его возвращает.</p><p>Из экипировки, рун и мастерства учитываются реализованные постоянные характеристики. Не моделируются условные эффекты комплектов и мастерства, большинство особых эффектов предметов и воспламенение от Гнева природы. Постоянные бонусы берутся из сборки; +13 от «Бронебойных болтов» второй раз не добавляется. Гнев природы включается до боя, не истекает по времени и расходует ровно 23 маны на снаряд по скриншоту RU (без повторной скидки). При мане ниже 10% он выключается; повторное включение допускается при восстановлении до 25% — это правило ротации модели. Для огня учтён заряд 21%, но воспламенение и связанные с ним эффекты пока не считаются. Коэффициенты Гнева природы соответствуют эпическому ур. 4. Для остальных реализованных умений принят эпический уровень 5. Откаты с таблицей прокачки берутся из её пятой строки; затем применяются специализации и скорость восстановления. Гарантии глобального максимума нет: выводится лучший проверенный вариант.</p><p>Источники: <a href="https://rutl.org/formuly/harakteristiki" target="_blank" rel="noopener">формулы RUTL</a>; <a href="https://rutl.org/builder" target="_blank" rel="noopener">каталог RUTL</a>; <a href="https://www.reddit.com/r/throneandliberty/comments/1k2cgcp/" target="_blank" rel="noopener">исследование формул Rabubu29</a>. Константы и спорные механики оставлены редактируемыми. Для RU нужна сверка с реальным пятиминутным боем.</p></div></details>
 <div id="sim-coverage" class="notice"></div><div class="sim-actions"><button id="simulate" class="equip-button">Симулировать 5 минут</button><button id="sim-cancel" hidden>Остановить</button><span id="sim-status" role="status" aria-live="polite"></span></div><progress id="sim-progress" value="0" max="180" hidden></progress><div id="sim-result"></div>`;
 function renderFields(){
  const p=simulationParams(getState(),catalog,assumptions);
  $('sim-character-fields').innerHTML=fields.filter(([key])=>!COMBAT_ASSUMPTION_KEYS.includes(key)).map(([key,label])=>`<div class="stat-line"><span>${esc(label)}</span><b>${num(p[key])}</b></div>`).join('');
  $('sim-fields').innerHTML=fields.filter(([key])=>COMBAT_ASSUMPTION_KEYS.includes(key)).map(([key,label])=>`<label>${label}<input data-param="${key}" type="number" min="${['ratingK','defenseK','regenPeriod','animationFloor'].includes(key)?'.01':'0'}" step="any" value="${p[key]}"></label>`).join('');
  $('sim-fields').querySelectorAll('input').forEach(el=>el.onchange=()=>{assumptions[el.dataset.param]=Number(el.value);invalidate();});
  $('sim-source-note').textContent='Для расчёта используются итоговые характеристики выбранной сборки: атрибуты, экипировка, трейты, руны, комплекты, мастерство и реализованные пассивные бонусы. Условные эффекты и часть пассивных прибавок ещё требуют сверки с игрой.';
 }
 const md=models(catalog,getState());$('sim-models').innerHTML=md.map(s=>`<tr><td>${esc(s.name)}</td><td>${num(s.cooldownSec)}</td><td><input data-cast="${s.id}" type="number" min="0" max="30" step="0.05" value="${s.cast}" aria-label="Время ${esc(s.name)}"></td><td><input data-pve="${s.id}" type="number" min="0" max="10" step="0.05" value="1" aria-label="Множитель ${esc(s.name)}"></td></tr>`).join('');
function warnings(){const ws=coverage(getState(),catalog);if($('sim-mode').value==='all')ws.push('Подбор ограничен реализованными умениями и специализациями. До 100 очков, без обязательного заполнения панели. Неизвестные эффекты не оптимизируются; пассивные фиксированы. Сравнивается DPS; активные вспомогательные специализации исключены. Ненужные действия и специализации удаляются проверочным прогоном. Поиск эвристический, глобальный максимум не гарантируется.');if(getState().passive.includes(PASS.thirst)&&getState().active.includes(IDS.laser))ws.push('«Жажда битвы» и «Луч погибели» выбраны вместе: луч работает, но взаимодействие пассивки с его отдельными эффектами требует подтверждения в игре.');$('sim-coverage').innerHTML=ws.length?`<b>Ограничения текущей сборки</b><ul>${ws.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:'Проверь допущения выше: результат остаётся расчётом модели, а не проверенным DPS RU.';}
 function invalidate(){if(result){dirty=true;$('sim-status').textContent='Сборка или настройки изменены — повтори симуляцию.';$('sim-result').classList.add('stale');}if(worker){worker.terminate();worker=null;$('simulate').disabled=false;$('sim-cancel').hidden=true;$('sim-progress').hidden=true;$('sim-status').textContent='Настройки изменились. Запусти расчёт заново.';}}
 function update(){const signature=JSON.stringify(getState());if(signature===lastState)return;lastState=signature;invalidate();renderFields();warnings();}
 for(const id of ['sim-mode','sim-budget','sim-night','sim-auto','sim-dotcrit','sim-formula'])$(id).onchange=()=>{invalidate();warnings();};
 $('sim-models').onchange=invalidate;
 $('sim-cancel').onclick=()=>{worker?.terminate();worker=null;$('simulate').disabled=false;$('sim-cancel').hidden=true;$('sim-progress').hidden=true;$('sim-status').textContent='Поиск остановлен.';};
 $('simulate').onclick=()=>{
  const state=structuredClone(getState()),params=simulationParams(state,catalog,assumptions);params.night=Number($('sim-night').checked);params.auto=Number($('sim-auto').checked);params.dotCrit=Number($('sim-dotcrit').checked);params.sheetIncludesPassives=1;params.resistanceModel=$('sim-formula').value;
  const mode=$('sim-mode').value,pool=mode==='all'?Object.values(IDS):state.active.filter(Boolean);
  const err=[];for(const [k] of fields)if(!Number.isFinite(params[k])||params[k]<0)err.push('Проверь числовые параметры.');for(const k of ['ratingK','defenseK','regenPeriod','interval','animationFloor'])if(params[k]<=0)err.push('Интервалы и константы должны быть больше нуля.');
  if((params.auto||pool.some(id=>id.startsWith('WP_CR')))&&(!params.crossMin||params.crossMax<params.crossMin))err.push('Выбери арбалет в экипировке.');if(pool.some(id=>id.startsWith('WP_WA'))&&(!params.wandMin||params.wandMax<params.wandMin))err.push('Выбери жезл в экипировке.');if(params.offMax>0&&params.offMax<params.offMin)err.push('Проверь диапазон парного арбалета.');if(params.offhand>100)err.push('Шанс парной атаки не может быть больше 100%.');if(mode==='selected'&&!pool.some(id=>Object.values(IDS).includes(id)))err.push('Выбери хотя бы одно поддерживаемое активное умение или включи подбор состава панели.');
  if(err.length){$('sim-status').textContent=[...new Set(err)].join(' ');$('sim-params').open=true;return;}
  const overrides={};$('sim-models').querySelectorAll('[data-cast]').forEach(el=>overrides[el.dataset.cast]={cast:Number(el.value)});$('sim-models').querySelectorAll('[data-pve]').forEach(el=>overrides[el.dataset.pve].pve=Number(el.value));if(Object.values(overrides).some(x=>!Number.isFinite(x.cast)||x.cast<0||x.cast>30||!Number.isFinite(x.pve)||x.pve<0||x.pve>10)){$('sim-status').textContent='Проверь время применения (0–30 с) и множители (0–10).';return;}
  runInput={catalog,state,params,overrides,mode,budget:Number($('sim-budget').value)};dirty=false;$('simulate').disabled=true;$('sim-cancel').hidden=false;$('sim-progress').hidden=false;$('sim-progress').max=runInput.budget;$('sim-progress').value=0;$('sim-status').textContent='Сравниваю ротации…';
  try{worker=new Worker(new URL('./sim-worker.js?v=automatic-key-nodes-2',import.meta.url),{type:'module'});}catch(e){$('simulate').disabled=false;$('sim-cancel').hidden=true;$('sim-progress').hidden=true;$('sim-status').textContent='Браузер не смог запустить расчёт. Обнови страницу и повтори.';return;}
  const finish=()=>{worker?.terminate();worker=null;$('simulate').disabled=false;$('sim-cancel').hidden=true;$('sim-progress').hidden=true;};
  worker.onerror=()=>{finish();$('sim-status').textContent='Ошибка расчёта. Проверь параметры и повтори запуск.';};
  worker.onmessage=e=>{const m=e.data;if(m.type==='progress'){$('sim-progress').value=m.done;$('sim-status').textContent=`${m.done} / ${m.budget} · лучший DPS ${num(m.dps)}`;}else if(m.type==='error'){finish();$('sim-status').textContent='Ошибка: '+m.message;}else{finish();result=m.result;renderResult();$('sim-status').textContent='Расчёт завершён.';}};worker.postMessage(runInput);
 };
 function renderResult(){
  const r=result,label=id=>catalog.skills.find(s=>s.id===id)?.name||names[id]||id,find=id=>catalog.skills.find(s=>s.id===id),gain=r.baseline>0?(r.dps/r.baseline-1)*100:0;
  const precombat=x=>x.id===IDS.nature&&x.time===0&&x.duration===0;
  const sourceIds=id=>({'nature-hit':[IDS.nature],'nature-lightning':[IDS.nature],'mark-hit':[IDS.mark],'mark-explosion':[IDS.mark],'curse-explosion':[IDS.burst],gale:[IDS.rapid,IDS.barrage,IDS.shot]}[id]||[id]);
  const specIcons=id=>{const specs=sourceIds(id).filter(id=>r.priority.includes(id)).flatMap(id=>(find(id)?.specializations||[]).filter(t=>(r.specs||runInput.state.specs)[id]?.includes(t.id)).map(t=>({...t,skill:label(id)})));return specs.length?`<span class="result-spec-icons" aria-label="Выбранные специализации">${specs.map(t=>`<img src="${esc(t.icon)}" alt="${esc(t.name)}" title="${esc(t.skill+': '+t.name)}" tabindex="0">`).join('')}</span>`:'';};
  const peak=Math.max(1,...r.bins.map(v=>v/10));
  $('sim-result').classList.remove('stale');$('sim-result').innerHTML=`${r.curseSearch?`<p class="notice">Связки проклятий: проверено ${r.curseSearch.tested} вариантов; лучший DPS среди них — ${num(r.curseSearch.bestDps)}. Проверены накопление 1–3 уровней, взрыв с сохранением и снятием проклятий. Это сравнение внутри текущей модели.</p>`:''}${r.natureElement===2?'<p class="notice"><b>Неполный расчёт огня:</b> воспламенение от «Гнева природы», его взрыв и связанные сокращения откатов пока не учтены. Показанный DPS не подходит для окончательного сравнения огненной сборки.</p>':''}<div class="sim-kpis"><div><small>Лучший найденный DPS</small><strong>${num(r.dps)}</strong><span>Средний урон в секунду · модель</span></div><div><small>Урон за 300 секунд</small><strong>${num(r.total)}</strong><span>${r.tested} проверенных вариантов</span></div><div><small>Изменение к исходному приоритету</small><strong>${gain>=0?'+':''}${num(gain)}%</strong><span>Исходный DPS: ${num(r.baseline)}</span></div></div>
  <p class="notice">Это результат экспериментальной модели с текущими допущениями. Поиск нашёл лучший из проверенных вариантов; это не доказанный максимум для RU. ${runInput.mode==='all'?'Подбирались активные умения и специализации. Пассивные и защитное умение фиксированы.':'Состав панели и специализации фиксированы.'}</p><details><summary>Характеристики этого прогона</summary><div class="sim-fields">${fields.map(([k,label])=>`<div><small>${esc(label)}</small><p>${num(runInput.params[k])}</p></div>`).join('')}</div><p class="micro">Ночь: ${runInput.params.night?'да':'нет'} · Автоатаки: ${runInput.params.auto?'да':'нет'} · Криты DoT: ${runInput.params.dotCrit?'да':'нет'}</p></details>
  ${runInput.mode==='all'?`<h3>Найденные специализации · ${r.specPoints} / 100 очков</h3><p class="micro">Распределение найдено в рамках модели. Вспомогательные и защитные: ${r.utilityPoints||0} очков; без прямой прибавки DPS на манекене. Эффекты по другим целям, перемещение и защита могут расходовать очки без прироста DPS на манекене.</p><div class="spec-allocation">${Object.entries(r.specs).filter(([,ids])=>ids.length).map(([id,ids])=>`<div><h4>${esc(label(id))}</h4>${(find(id)?.specializations||[]).filter(t=>ids.includes(t.id)).map(t=>`<p><img src="${esc(t.icon)}" alt=""><span>${esc(t.name)} · ${ROLE_LABELS[specializationRole(id,Number(t.id.split("_").at(-1)))]}</span><small>${t.cost} оч.</small></p>`).join('')}</div>`).join('')}</div>${r.warnings?.length?`<details><summary>Ограничения найденной панели</summary><ul>${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></details>`:''}`:''}
  <details><summary>Проверка взаимодействий и поиска</summary><p class="micro">Формула: ${runInput.params.resistanceModel==='difference'?'Rabubu29 — разность рейтингов':'RUTL / WTFOMG PvE'}. Одинаковые характеристики, пассивные умения, цель и 300 секунд. Контрольные панели заданы отдельно от поиска; это проверка модели, а не эталон игры или билд Арагона. Полный поиск сохраняет лучший результат исходной и контрольных панелей.</p><div class="sim-table-wrap"><table><thead><tr><th>Вариант</th><th>DPS</th></tr></thead><tbody><tr><td>Исходная панель и приоритет</td><td>${num(r.baseline)}</td></tr><tr><td>Лучший найденный</td><td>${num(r.dps)}</td></tr>${(r.referenceTrials||[]).map(row=>`<tr><td><details><summary>${esc(row.name)}</summary><ol>${row.priority.map(id=>`<li>${esc(label(id))}: ${(find(id)?.specializations||[]).filter(t=>row.specs[id]?.includes(t.id)).map(t=>esc(t.name)).join(', ')||'без специализаций'}</li>`).join('')}</ol></details></td><td>${num(row.dps)}</td></tr>`).join('')}</tbody></table></div>${r.interaction?`<p>Те же приоритеты, но численные бонусы «Света доблести» и личного «Часа преодоления» отключены: <b>${num(r.interaction.withoutPersonalBonuses)} DPS</b>. Разница с результатом: <b>${num(r.interaction.personalBonusDelta)} DPS</b>.</p><p class="micro">Баффы остаются в панели, расходуют время и ману; их длительность не меняется. Это вклад их численных эффектов; сравнение не означает, что удаление кнопок даст тот же результат. Усиленный ими урон записан на атакующие умения.</p>`:''}${runInput.params.defenseK!==2500?'<p class="notice">Используется сохранённая пользовательская константа защиты. В формуле RUTL — 2500; своё значение можно изменить в параметрах. При нулевой защите различий нет.</p>':''}</details>
  <h3>DPS по отрезкам в 10 секунд</h3><div class="dps-chart" role="img" aria-label="Урон в секунду по десятисекундным отрезкам">${r.bins.map((d,i)=>`<div title="${i*10}–${(i+1)*10} с: ${num(d/10)} DPS"><span style="height:${Math.max(1,d/10/peak*100)}%"></span><small>${i%5===0?i*10:''}</small></div>`).join('')}</div><div class="chart-axis"><span>0 с</span><span>300 с</span></div>
  <h3>Приоритеты найденной панели</h3><p class="micro">Значки рядом с умениями — выбранные специализации этого прогона. Наведи курсор на значок, чтобы увидеть название. Неучтённые эффекты перечислены в ограничениях модели.</p>${r.priority.includes(IDS.nature)?'<p class="notice">Перед боем: включить «Гнев природы». В бою поддерживается выбранная стихия; повторное включение после отключения — при мане от 25%.</p>':''}<p class="hint">На каждом шаге используется первое доступное умение из списка. Условия учитывают ману, откаты и проклятия; это не фиксированный повторяющийся цикл. Бедственное слово ждёт ${r.burstStacks} ур. «Касания скорби», если оно есть в панели.</p><div class="rotation-priority">${r.priority.filter(id=>id!==IDS.nature).map((id,i)=>`<div><span>${i+1}</span><img src="${esc(find(id)?.thumbnail)}" alt=""><b>${esc(label(id))}</b>${specIcons(id)}</div>`).join('')}</div><div class="sim-actions"><button id="sim-apply">Применить найденную панель</button><button id="sim-download">Скачать полный журнал CSV</button></div>
  <p class="weapon-in-hand"><b>Этот прогон: арбалет в руках</b><span>${runInput.params.auto?'Автоатаки включены':'Автоатаки выключены'} · 300 секунд · 1 цель</span></p><div class="sim-result-columns"><div class="result-panel"><h3>Вклад в урон</h3><p class="micro">Показан источник попадания. Прибавки от баффов входят в урон усиленных атак; сравнение их эффекта — в блоке проверки взаимодействий.</p><div class="sim-table-wrap"><table><thead><tr><th>Источник</th><th>Применений</th><th>Урон</th><th>DPS</th><th>Доля</th></tr></thead><tbody>${Object.entries(r.damage).sort((a,b)=>b[1]-a[1]).map(([id,d])=>`<tr><td><span class="damage-source">${find(id)?.thumbnail?`<img src="${esc(find(id).thumbnail)}" alt="">`:''}<span>${esc(label(id))}${specIcons(id)}</span></span></td><td>${r.counts[id]||'—'}</td><td>${num(d)}</td><td>${num(d/300)}</td><td>${num(r.total?d/r.total*100:0)}%</td></tr>`).join('')}</tbody></table></div><p class="micro">Мана в конце: ${num(r.mana)}; минимум: ${num(r.minMana)}. Паузы из-за маны: ${num(r.starved)} с. Здоровье в конце: ${num(r.hp)}.</p><p class="micro">Гнев природы: активен ${num(r.natureUptime)} с; расход маны ${num(r.natureMana)}; отключений ${r.natureStops}. Включение до боя показано первым действием.</p></div><div class="result-panel"><h3>Ротация за 5 минут</h3><p class="micro">${r.logs.length} действий · «—» означает включение до начала боя. Мана указана после применения.</p><ol class="rotation-log">${r.logs.map(x=>`<li class="${precombat(x)?'precombat-action':''}"><time title="${precombat(x)?'До боя':''}">${precombat(x)?'—':num(x.time)+' с'}</time><img class="rotation-skill-icon" src="${esc(find(x.id)?.thumbnail)}" alt=""><span class="rotation-action"><b>${esc(x.name)}</b>${specIcons(x.id)}</span><small class="rotation-mana" title="Мана после применения">${num(x.mana)} MP</small></li>`).join('')}</ol></div></div>`;
  $('sim-apply').onclick=()=>{if(dirty){$('sim-status').textContent='Сначала повтори расчёт для изменённой сборки.';return;}apply(r.priority.includes(IDS.nature)?[IDS.nature,...r.priority.filter(id=>id!==IDS.nature)]:r.priority,r.specs);$('sim-status').textContent='Найденная панель и её специализации применены. Порядок слотов соответствует приоритетам.';};
  $('sim-download').onclick=()=>{const lines=['time_seconds;skill;mana_after_cast',...r.logs.map(x=>`${precombat(x)?'-':x.time};"${x.name.replaceAll('"','""')}";${x.mana}`)];const blob=new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fury-rotation-300s.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 }
 const saved=profile?.get('simulation');
 if(saved){
  for(const key of COMBAT_ASSUMPTION_KEYS)if(Number.isFinite(saved.assumptions?.[key]))assumptions[key]=saved.assumptions[key];
  for(const [id,value] of Object.entries(saved.controls||{})){const el=$(id);if(!controlIds.includes(id)||!el)continue;if(el.type==='checkbox'&&typeof value==='boolean')el.checked=value;else if([...el.options||[]].some(o=>o.value===value))el.value=value;}
  for(const el of $('sim-models').querySelectorAll('input')){const kind=el.dataset.cast?'cast':'pve',id=el.dataset.cast||el.dataset.pve,value=saved.overrides?.[id]?.[kind];if(Number.isFinite(value))el.value=value;}
 }
 function persist(){
  const controls=Object.fromEntries(controlIds.map(id=>[id,$(id).type==='checkbox'?$(id).checked:$(id).value])),overrides={};
  for(const el of $('sim-fields').querySelectorAll('input'))if(el.value!==''&&Number.isFinite(Number(el.value)))assumptions[el.dataset.param]=Number(el.value);
  for(const el of $('sim-models').querySelectorAll('input')){const id=el.dataset.cast||el.dataset.pve;overrides[id]??={};if(el.value!==''&&Number.isFinite(Number(el.value)))overrides[id][el.dataset.cast?'cast':'pve']=Number(el.value);}
  profile?.save('simulation',{assumptions,controls,overrides});
 }
 root.addEventListener('input',persist);root.addEventListener('change',persist);
 renderFields();warnings();return {update};
}
